import {compute,draft,norm,dedupe} from './engine.js';
import {JobGraph} from './job-graph.js';
import {mergeDemoRows} from './demo-state.js';
import * as ctx from './context.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pln=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'PLN',maximumFractionDigits:0}).format(n);
const labels={pending:'Awaiting decision',agreed:'Agreed',completed:'Done · not paid',paid:'Paid'};
const titles={overview:['Overview','Overview',''],sources:['Messages','Messages',''],jobs:['Jobs','Jobs',''],tasks:['Action plan','To do','']};
let state={rows:[],date:'2026-10-30',replay:0},view='overview',model,demo;
let clarifyingSource=null,server=[],link=null;
const jobGraph=new JobGraph($('#graph'),{onJob:id=>details(id),onTask:(id,type)=>details(id,type),onGap:record=>{messageDialog(true);clarifyingSource=record.source_id;}});
let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function persist(){try{localStorage.setItem('fieldbook-v1',JSON.stringify(state));}catch{toast('No room to save. Download the JSON state before closing.');}}
function go(tab){view=tab;$$('[data-page]').forEach(p=>p.hidden=p.dataset.page!==tab);$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#crumb').textContent=titles[tab][0];$('#page-title').textContent=titles[tab][1];$('#page-description').textContent=titles[tab][2];$('#page-description').hidden=!titles[tab][2];history.replaceState(null,'','#'+tab);if(tab==='jobs')requestAnimationFrame(()=>jobGraph.layout());}
function sourceCard(r){return `<article class="source-card"><div class="source-meta"><span>${esc(r.source_id)} · ${esc(r.channel)}</span><time>${esc(r.sent_at.slice(5,16).replace('T',' '))}</time></div><h3>${esc(r.conversation_title||'Note')} · ${esc(({owner:'owner',customer:'customer',worker:'crew',supplier:'supplier'})[r.author_role]||r.author_role)}</h3><p>${esc(r.raw_text)}</p>${(r.attachments||[]).map(a=>`<p class="attachment">↳ ${esc(a.filename)} · text not available</p>`).join('')}</article>`;}
function taskRows(limit=model.tasks.length){return model.tasks.slice(0,limit).map(t=>{const j=model.jobs.find(j=>j.id===t.job);return `<div class="task-row"><div class="task-icon">${({decision:'↗',budget:'≠',schedule:'◷',payment:'€'})[t.type]}</div><div class="task-text"><strong>${esc(t.title)}</strong><span>${esc(j.address)} · ${pln(j.amount)}${t.due?' · contact '+esc(t.due.slice(5)):''}</span></div><button data-task="${esc(t.id)}">Write</button></div>`;}).join('')||'<p class="muted">No open items in the data so far.</p>';}
function render(){
 model=compute([...state.rows,...server],state.date+'T23:59:59+01:00');$('#report-date').value=state.date;
 $('#empty').hidden=state.rows.length>0;$('#app-content').hidden=!state.rows.length;
 $('#nav-count').textContent=model.unique;$('#task-count').textContent=model.tasks.length;
 for(const k of ['pending','agreed','paid'])$('#stat-'+k).textContent=pln(model.totals[k]);
 $('#flow-input').textContent=state.rows.length+server.length;$('#flow-unique').textContent=model.unique;$('#flow-jobs').textContent=model.jobs.length;
 $('#dashboard-tasks').innerHTML=taskRows(3);$('#all-tasks').innerHTML='<div class="panel-heading"><h2>To do · '+model.tasks.length+'</h2></div>'+taskRows();
 const max=Math.max(...Object.values(model.totals),1);
 $('#bars').innerHTML=[['pending','Quotes in progress'],['agreed','Agreed work'],['completed','Done, not settled'],['paid','Confirmed payments']].map(([k,n])=>`<div class="bar-line"><div class="bar-label"><span>${n}</span><span>${pln(model.totals[k])}</span></div><div class="bar-track"><div class="bar" style="width:${model.totals[k]/max*100}%"></div></div></div>`).join('');
 $('#gap-panel').hidden=!model.gaps.length;
 $('#gap-panel').innerHTML=model.gaps.length?`<div class="gap-content"><h2>Customer missing</h2><p>“${esc(model.gaps[0].raw_text.slice(0,65))}…”</p></div><button class="quiet" id="clarify">Fill in</button>`:'';
 jobGraph.setModel(model,state.date);
 ctx.workflow($('#workflow'),model,server,link);ctx.latest($('#latest'),server,model);ctx.proposals($('#proposals'),server,model);
 renderSources();$('#replay-steps').innerHTML=['Note clarified','Quote accepted','Work done','Payment confirmed'].map((n,i)=>`<div class="step ${i<state.replay?'done':''}">${i<state.replay?'✓ ':''}${n}<small>${['30 Oct · 08:05','30 Oct · 08:10','2 Nov · 16:40','3 Nov · 10:15'][i]}</small></div>`).join('');
 $('#replay').disabled=state.replay>=demo.events.length;$('#replay').textContent=state.replay>=demo.events.length?'Scenario finished ✓':'Next event →';
 $('#replay-description').textContent=state.replay?['The owner clarified the note. The task for Ewa was merged.','The customer accepted 4300 PLN. Next step: setting the date.','Work done. The amount is waiting for payment confirmation.','Payment confirmed by the owner. The report now covers 3 November.'][state.replay-1]:'Prepared demo events. The clock moves forward openly with them.';
 persist();
}
function renderSources(){const q=norm($('#search').value);const rows=model.sources.filter(r=>Date.parse(r.sent_at)<=Date.parse(state.date+'T23:59:59+01:00')).filter(r=>!q||norm(r.raw_text+' '+r.conversation_title+' '+r.source_id).includes(q));$('#source-list').innerHTML=rows.slice().reverse().map(sourceCard).join('')||'<p>No messages match the search.</p>';}
function details(id,type){const j=model.jobs.find(j=>j.id===id);if(!j)return;$('#detail-title').textContent=j.address+' · '+j.customer;
 $('#detail-body').innerHTML=`<span class="pill ${j.status}">${labels[j.status]}</span><h3>Current amount</h3><h2>${pln(j.amount)}</h2>${j.excludes.length?'<p class="muted">Out of scope: '+esc(j.excludes.join(', '))+'</p>':''}${type?`<h3>Message to the customer</h3><div class="draft" id="draft-text">${esc(draft(j,type))}</div><button id="copy-draft" class="primary">Copy message</button><p class="form-note">Copy it and send it to the customer. Then add their reply.</p>`:''}<details class="detail-fold"><summary>Change history</summary>${j.history.map(h=>{const show=v=>h.field==='amount'?pln(v):h.field==='status'?(labels[v]||v):String(v);return `<div class="history-row">${h.field==='amount'&&h.from===0?'First quote':esc(({amount:'Quote',status:'Status'})[h.field]||h.field)}: ${h.field==='amount'&&h.from===0?'':esc(show(h.from))+' → '}<strong>${esc(show(h.to))}</strong><br><small>${esc(h.at.slice(0,10))}</small></div>`;}).join('')}</details><details class="detail-fold"><summary>Messages (${j.evidence.length})</summary>${j.evidence.map(s=>model.sources.find(r=>r.source_id===s)).filter(Boolean).reverse().map(sourceCard).join('')}</details>`;
 $('#detail-dialog').showModal();$('#copy-draft')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(draft(j,type));toast('Message copied.');}catch{toast('Select and copy the draft text.');}});
}
function messageDialog(clarify=false){clarifyingSource=clarify?model.gaps[0]?.source_id:null;$('#message-job').innerHTML=(clarify?'<option value="">Pick the customer from the note</option>':link?'<option value="">Let Fieldbook work it out</option>':'')+model.jobs.map(j=>`<option value="${esc(j.id)}">${esc(j.address)} · ${esc(j.customer)}</option>`).join('');$('#message-date').value=state.date;$('#message-text').value='';$('#message-author').value=clarify?'owner':'customer';$('#message-channel').value=clarify?'correction':'chat';$('#message-note').textContent=link?'Fieldbook reads it against the job\'s history and shows what changed.':'The context layer is not connected: the rules engine reads it on this device.';if(clarify){$('#message-text').placeholder='Which customer is “the lady behind the bakery”, and what do we need to do?';}else $('#message-text').placeholder='e.g. yes, we confirm 4300 PLN without the cabin';$('#message-dialog').showModal();}
function append(records){const candidate=[...state.rows,...records];compute(candidate,state.date+'T23:59:59+01:00');state.rows=candidate;render();}
function loadDemo(){state={rows:demo.messages,date:'2026-10-30',replay:0,fixtureVersion:demo.fixture_version};render();go('overview');toast('Demo loaded: '+state.rows.length+' entries, '+model.unique+' sources.');}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab],[data-goto]');if(tab)go(tab.dataset.tab||tab.dataset.goto);const j=e.target.closest('[data-job]');if(j)details(j.dataset.job);const task=e.target.closest('[data-task]');if(task){const t=model.tasks.find(t=>t.id===task.dataset.task);details(t.job,t.type);}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();if(e.target.closest('#clarify'))messageDialog(true);const d=e.target.closest('[data-decide]');if(d){d.disabled=true;ctx.decide(d.dataset.id,d.dataset.decide).then(row=>{server=server.map(r=>r.source_id===row.source_id?row:r);render();toast(row.reading.action.status==='approved'?'Approved. The agent can go ahead.':'Dismissed.');}).catch(err=>{d.disabled=false;toast(err.message);});}});
$('#new-message').onclick=()=>model.jobs.length?messageDialog():toast('Load the demo or import messages first.');
$('#search').oninput=renderSources;$('#report-date').onchange=e=>{if(!e.target.value)return;state.date=e.target.value;render();};
$('#message-form').onsubmit=async e=>{e.preventDefault();const id=$('#message-job').value,j=model.jobs.find(j=>j.id===id);const text=$('#message-text').value.trim(),date=$('#message-date').value;if(!text)return;
 if(link){const button=e.submitter;if(button)button.disabled=true;try{const row=await ctx.send(text,model,{date,job:id,author_role:$('#message-author').value,channel:$('#message-channel').value,clarifies:clarifyingSource});server=[...server.filter(r=>r.source_id!==row.source_id),row];if(date>state.date)state.date=date;render();$('#message-dialog').close();go('overview');toast('Sent to the context layer. Reading it now.');}catch(err){toast(err.message);}finally{if(button)button.disabled=false;}return;}
 if(!j){toast('Pick the job this message is about.');return;}
 const r={source_id:'U_'+crypto.randomUUID(),channel:$('#message-channel').value,thread_id:'manual_'+j.id,contact_key:null,conversation_title:j.customer,job_context:j.id,author_role:$('#message-author').value,sent_at:date+'T12:00:00+01:00',raw_text:text,...(clarifyingSource?{clarifies_source_id:clarifyingSource}:{})};try{append([r]);state.date=date;render();$('#message-dialog').close();toast('Message saved. State recalculated.');}catch(err){toast(err.message);}};
$('#replay').onclick=()=>{if(state.replay>=demo.events.length)return;const r=demo.events[state.replay];state.rows=[...state.rows,r];state.replay++;state.date=r.sent_at.slice(0,10);render();toast('Added '+r.source_id+' · '+r.raw_text.slice(0,75)+'…');};
$('#load-demo').onclick=loadDemo;$('#reset').onclick=()=>{if(confirm('Restore the demo data? This removes changes saved in this browser.')){server=[];ctx.reset();loadDemo();}};
$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('The import limit is 5 MB.');const text=await file.text();let rows;try{const value=JSON.parse(text);rows=Array.isArray(value)?value:value.messages||value.rows;}catch{rows=text.trim().split(/\r?\n/).map(JSON.parse);}if(!Array.isArray(rows))throw Error('Choose JSONL or a JSON array of messages.');dedupe(rows);const uniqueBefore=dedupe(state.rows).length;append(rows);toast('Added '+(dedupe(state.rows).length-uniqueBefore)+' new sources. Repeats do not change amounts.');}catch(err){toast('Import stopped: '+err.message);}finally{e.target.value='';}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({date:state.date,rows:state.rows,report:model},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fieldbook-state.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(titles[tab])go(tab);});
try{const response=await fetch('./demo.json');if(!response.ok)throw Error('Could not load the demo.');demo=await response.json();try{const stored=JSON.parse(localStorage.getItem('fieldbook-v1'));if(stored&&Array.isArray(stored.rows)&&/^\d{4}-\d{2}-\d{2}$/.test(stored.date)){dedupe(stored.rows);state=stored;}else state.rows=demo.messages;}catch{state.rows=demo.messages;}const seed=demo.messages.find(r=>r.source_id==='S01');if(state.fixtureVersion!==demo.fixture_version&&state.rows.some(r=>r.source_id==='S01'&&r.raw_text===seed?.raw_text)){state.rows=mergeDemoRows(state.rows,demo.messages);state.fixtureVersion=demo.fixture_version;}render();go(titles[location.hash.slice(1)]?location.hash.slice(1):'overview');link=await ctx.health();ctx.sidebar(link);if(link){render();ctx.follow(rows=>{server=rows;const last=rows.map(r=>r.sent_at.slice(0,10)).sort().pop();if(last&&last>state.date)state.date=last;render();});}}catch(err){$('#empty').hidden=false;$('#app-content').hidden=true;$('#empty').textContent=err.message;}
